class Article < ApplicationRecord
  scope :published, -> { where(status: "published") }
  scope :recent,    -> { order(created_at: :desc).limit(10) }
  scope :by_tag,    ->(tag) { joins(:tags).where(tags: { name: tag }) }
end

Article.published.recent
