RSpec.describe PostsController, type: :request do
  include ActiveJob::TestHelper

  it "enqueues a welcome email after user creation" do
    expect {
      post "/users", params: { user: { email: "test@example.com" } }
    }.to have_enqueued_job(WelcomeEmailJob)
      .with(instance_of(Integer))
      .on_queue("default")
  end
end

class PostsController < ApplicationController
  def show
    @post = Post.find(params[:id])

    respond_to do |format|
      format.html  # render app/views/posts/show.html.erb
      format.json { render json: @post }
      format.xml  { render xml: @post }
    end
  end
end

# spec/support/database_cleaner.rb
RSpec.configure do |config|
  config.before(:suite) { DatabaseCleaner.strategy = :transaction }
  config.around(:each)  { |ex| DatabaseCleaner.cleaning { ex.run } }

  # System tests cần truncation vì Capybara dùng thread riêng
  config.before(:each, type: :system) { DatabaseCleaner.strategy = :truncation }
end

class Order < ApplicationRecord
  after_save    { Rails.logger.info "trong transaction" }
  after_commit  { PaymentMailer.receipt(self).deliver_later }
end
